package lint

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// writeOptionalProtoPkg lays down a project whose handler Deps hold an
// optional pointer to a protobuf message generated into the project
// (gen/config/v1/config.pb.go), beside an optional pointer to a hand-written
// struct with a Get method, and an optional pointer to a message-shaped type
// in a package outside the module. The message's package also holds Get
// methods that are not generated getters: one hand-written beside the
// generated file, one in a *.pb.go without the generated header, and one in
// the generated file without the nil-receiver check.
func writeOptionalProtoPkg(t *testing.T, projectDir, methods string) {
	t.Helper()
	write := func(rel, body string) {
		t.Helper()
		p := filepath.Join(projectDir, filepath.FromSlash(rel))
		if err := os.MkdirAll(filepath.Dir(p), 0o755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(p, []byte(body), 0o644); err != nil {
			t.Fatal(err)
		}
	}
	write("go.mod", "module example.com/app\n\ngo 1.25\n")
	write("gen/config/v1/config.pb.go", `// Code generated by protoc-gen-go. DO NOT EDIT.

package configv1

type Config struct {
	Foo  string
	Name *string
	Qux  int32
	Kind isConfig_Kind
}

type isConfig_Kind interface{ isConfig_Kind() }

type Config_Baz struct{ Baz string }

func (*Config_Baz) isConfig_Kind() {}

const Default_Config_Name = "n"

func (x *Config) GetFoo() string {
	if x != nil {
		return x.Foo
	}
	return ""
}

func (x *Config) GetName() string {
	if x != nil && x.Name != nil {
		return *x.Name
	}
	return Default_Config_Name
}

func (x *Config) GetBaz() string {
	if x != nil {
		if x, ok := x.Kind.(*Config_Baz); ok {
			return x.Baz
		}
	}
	return ""
}

func (x *Config) GetQux() int32 {
	if x == nil {
		return 0
	}
	return x.Qux
}

func (x *Config) GetRaw() string {
	return x.Foo
}

func (x *Config) Reset() { *x = Config{} }
`)
	// Hand-written beside the generated file, in the same package.
	write("gen/config/v1/config_ext.go", `package configv1

func (x *Config) GetDanger() string { return x.Foo }

func (x *Config) GetCareful() string {
	if x != nil {
		return x.Foo
	}
	return ""
}
`)
	// A *.pb.go name without the generated header.
	write("gen/config/v1/extra.pb.go", `package configv1

func (x *Config) GetUnmarked() string {
	if x != nil {
		return x.Foo
	}
	return ""
}
`)
	write("internal/handlers/fixture/service.go", `package fixture

import (
	configv1 "example.com/app/gen/config/v1"
	extv1 "example.org/other/gen/ext/v1"
)

// Plain is hand-written: its Get method is not nil-safe.
type Plain struct {
	foo string
}

func (p *Plain) GetFoo() string { return p.foo }

type Deps struct {
	// forge:optional-dep
	Cfg *configv1.Config
	// forge:optional-dep
	Plain *Plain
	// forge:optional-dep
	Ext *extv1.Config
}

type Service struct {
	deps Deps
}

func New(deps Deps) *Service { return &Service{deps: deps} }
`)
	write("internal/handlers/fixture/handlers.go", "package fixture\n\n"+methods)
}

// TestOptionalDepsGuard_ProtoGetter pins forge#2282 row 41603cd7: a
// protoc-gen-go getter on an optional proto-message dep is nil-safe, so it
// is not flagged — and nothing else about that dep, or a Get on any other
// type, gets the same pass.
func TestOptionalDepsGuard_ProtoGetter(t *testing.T) {
	t.Parallel()

	cases := []struct {
		name    string
		methods string
		want    []string // fields flagged, in order; nil → no findings
	}{
		{
			name: "getter-not-flagged",
			methods: `
func (s *Service) Call() string {
	return s.deps.Cfg.GetFoo()
}
`,
		},
		{
			name: "getter-through-alias-not-flagged",
			methods: `
func (s *Service) Call() string {
	cfg := s.deps.Cfg
	return cfg.GetFoo()
}
`,
		},
		{
			name: "generated-getter-shapes-not-flagged",
			methods: `
func (s *Service) Call() (string, string, int32) {
	return s.deps.Cfg.GetName(), s.deps.Cfg.GetBaz(), s.deps.Cfg.GetQux()
}
`,
		},
		{
			// forge#2357 review B1: the message being generated does not make
			// every Get method on it a generated getter.
			name: "hand-written-get-on-message-flagged",
			methods: `
func (s *Service) Call() string {
	return s.deps.Cfg.GetDanger()
}
`,
			want: []string{"Cfg"},
		},
		{
			name: "hand-written-nil-checked-get-on-message-flagged",
			methods: `
func (s *Service) Call() string {
	return s.deps.Cfg.GetCareful()
}
`,
			want: []string{"Cfg"},
		},
		{
			name: "get-in-pb-go-without-generated-header-flagged",
			methods: `
func (s *Service) Call() string {
	return s.deps.Cfg.GetUnmarked()
}
`,
			want: []string{"Cfg"},
		},
		{
			name: "generated-get-without-nil-check-flagged",
			methods: `
func (s *Service) Call() string {
	return s.deps.Cfg.GetRaw()
}
`,
			want: []string{"Cfg"},
		},
		{
			name: "undeclared-get-flagged",
			methods: `
func (s *Service) Call() string {
	return s.deps.Cfg.GetMissing()
}
`,
			want: []string{"Cfg"},
		},
		{
			name: "field-access-flagged",
			methods: `
func (s *Service) Call() string {
	return s.deps.Cfg.Foo
}
`,
			want: []string{"Cfg"},
		},
		{
			name: "non-getter-method-flagged",
			methods: `
func (s *Service) Call() {
	s.deps.Cfg.Reset()
}
`,
			want: []string{"Cfg"},
		},
		{
			name: "method-value-flagged",
			methods: `
func (s *Service) Call() func() string {
	return s.deps.Cfg.GetFoo
}
`,
			want: []string{"Cfg"},
		},
		{
			name: "get-on-non-proto-type-flagged",
			methods: `
func (s *Service) Call() string {
	return s.deps.Plain.GetFoo()
}
`,
			want: []string{"Plain"},
		},
		{
			name: "get-on-type-outside-the-module-flagged",
			methods: `
func (s *Service) Call() string {
	return s.deps.Ext.GetFoo()
}
`,
			want: []string{"Ext"},
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			projectDir := t.TempDir()
			writeOptionalProtoPkg(t, projectDir, tc.methods)
			got, err := collectOptionalDepsGuardFindings(projectDir)
			if err != nil {
				t.Fatal(err)
			}
			var fields []string
			for _, f := range got {
				fields = append(fields, f.Field)
			}
			if strings.Join(fields, ",") != strings.Join(tc.want, ",") {
				t.Fatalf("flagged %v, want %v: %+v", fields, tc.want, got)
			}
		})
	}
}
